const ZW = String.fromCharCode(8203);
// 10/10: mensagem citada (o Daniel/cliente respondeu a uma mensagem específica do Dyno).
const ctxCit = (m, d) => (m.extendedTextMessage && m.extendedTextMessage.contextInfo) || (m.imageMessage && m.imageMessage.contextInfo) || (m.audioMessage && m.audioMessage.contextInfo) || (m.documentMessage && m.documentMessage.contextInfo) || (m.videoMessage && m.videoMessage.contextInfo) || (m.documentWithCaptionMessage && m.documentWithCaptionMessage.message && m.documentWithCaptionMessage.message.documentMessage && m.documentWithCaptionMessage.message.documentMessage.contextInfo) || d.contextInfo || null;
const textoCitado = (m, d) => {
  const cx = ctxCit(m, d);
  const q = (cx && cx.quotedMessage) || null;
  if (!q) return '';
  const t = q.conversation || (q.extendedTextMessage && q.extendedTextMessage.text) || (q.imageMessage && (q.imageMessage.caption || '[foto]')) || (q.videoMessage && (q.videoMessage.caption || '[vídeo]')) || (q.documentMessage && (q.documentMessage.caption || q.documentMessage.fileName || '[arquivo]')) || (q.audioMessage ? '[áudio]' : '') || '';
  return String(t).split(String.fromCharCode(8203)).join('').trim().slice(0, 1200);
};
// Resposta curta do admin a um aviso (Beta, pedido de função, lead do Business) vira o comando correspondente.
const comandoCitado = (t, c) => {
  if (!c) return '';
  const tl = String(t || '').trim().toLowerCase();
  if (!tl || tl.length > 40) return '';
  const SIM = /^(sim|ok|pode|aprov\w*|manda|libera\w*|confirm\w*|isso|bora)(\s|$|[.!,])|^(👍|✅)/u.test(tl);
  const NAO = /^(n[ãa]o|recus\w*|nega\w*|arquiv\w*|descart\w*)(\s|$|[.!,])|^(👎|❌)/u.test(tl);
  const FEITO = /^(feito|pronto|implantad\w*|fiz|conclu\w*|entregue)(\s|$|[.!,])/u.test(tl);
  let r = c.match(/Pedido para o Beta\*?\s*\(n[º°o.]?\s*(\d+)\)/i);
  if (r) return SIM ? 'aprovar ' + r[1] : (NAO ? 'recusar ' + r[1] : '');
  r = c.match(/Pedido de fun[çc][ãa]o #(\d+)/i);
  if (r) return FEITO ? 'admin pedido ' + r[1] + ' feito' : (SIM ? 'admin pedido ' + r[1] + ' sim' : (NAO ? 'admin pedido ' + r[1] + ' nao' : ''));
  r = c.match(/Dyno Business:[^\n]*?\(n[º°o.]?\s*(\d+)\)/i);
  if (r && SIM) return 'admin business lead ' + r[1];
  return '';
};
const raw = $input.first().json.body || $input.first().json;
const evento = String(raw.event || '').toLowerCase().replace('_', '.');
if (evento && evento !== 'messages.upsert') return [];
const d = Array.isArray(raw.data) ? (raw.data[0] || {}) : (raw.data || {});
const key = d.key || {};
const jid = String(key.remoteJid || '');
if (!jid || jid.includes('@g.us') || jid.includes('broadcast') || jid.includes('newsletter') || jid.startsWith('status@')) return [];
if (key.fromMe === true) return [];
const digitos = s => String(s || '').split('@')[0].split(':')[0].replace(/\D/g, '');
const alt = key.remoteJidAlt || key.senderPn || d.senderPn || '';
const numero = jid.endsWith('@lid') ? digitos(alt) : digitos(jid);
const m = d.message || {};
let texto = m.conversation || (m.extendedTextMessage && m.extendedTextMessage.text) || '';
if (m.buttonsResponseMessage) texto = m.buttonsResponseMessage.selectedDisplayText || texto;
if (m.listResponseMessage) texto = m.listResponseMessage.title || texto;
texto = String(texto || '').trim();
if (!texto || texto.startsWith(ZW)) return [];
if (!/^55[0-9]{10,11}$/.test(numero)) return [];
const citada = textoCitado(m, d);
if (numero === '5511930851325' && citada) { const cmd = comandoCitado(texto, citada); if (cmd) texto = cmd; }
const cpfValido = c => {
  if (c.length !== 11 || /^(\d)\1{10}$/.test(c)) return false;
  const dv = n => { let s = 0; for (let i = 0; i < n; i++) s += Number(c[i]) * (n + 1 - i); const r = (s * 10) % 11; return r === 10 ? 0 : r; };
  return dv(9) === Number(c[9]) && dv(10) === Number(c[10]);
};
let textoRpc = texto.slice(0, 500);
let cpf = '';
if (/^__cpf_/.test(textoRpc)) textoRpc = '(texto)';
const soDig = texto.replace(/[\s.\-]/g, '');
if (/^[0-9]{11}$/.test(soDig)) {
  if (cpfValido(soDig)) { cpf = soDig; textoRpc = '__cpf_ok__'; } else { textoRpc = '__cpf_invalido__'; }
}
return [{ json: { numero: numero, texto: textoRpc, cpf: cpf, nome: String(d.pushName || ''), citada } }];

// 07/10/2026: mensagem de cadastro concluído (reescrita com primeiros passos e área do cliente). Com `sem_teste` (dyno_sem_teste): sem 60 dias grátis; o ciclo já foi escolhido no cadastro, então pede só PIX ou CARTÃO.
const ZW = String.fromCharCode(8203);
const NL = String.fromCharCode(10);
const numero = $('Normalizar mensagem').first().json.numero;
const p = $('Supabase: passo do cadastro').first().json;
let cli = {};
try { cli = $('Asaas: criar cliente').first().json || {}; } catch (e) { }
const falha = !cli.id;
const venc = String(p.vencimento || '').split('-').reverse().join('/');
const primeiro = String(p.nome || '').split(' ')[0];
const NIVEL = { essencial: 'Essencial', completo: 'Completo', premium: 'Premium' };
const PRECO = { essencial: ['19,90', '199,90'], completo: ['29,90', '299,90'], premium: ['39,90', '399,90'] };
const nv = String(p.nivel || 'completo').toLowerCase();
const plano = NIVEL[nv] || '';
const pr = PRECO[nv] || PRECO.completo;
const anual = String(p.ciclo || 'MONTHLY').toUpperCase() === 'YEARLY';
const valor = (p.valor != null && p.valor !== '') ? Number(p.valor).toFixed(2).replace('.', ',') : (anual ? pr[1] : pr[0]);
let t = '🎉 *Cadastro concluído, ' + primeiro + '!*' + NL;
if (p.sem_teste === true) {
  t += 'Plano *' + plano + ' ' + (anual ? 'anual' : 'mensal') + '* (R$ ' + valor + (anual ? ' por ano' : ' por mês') + '). Para liberar o Dyno e a Dina, como prefere pagar: *PIX* ou *CARTÃO*?' + NL + NL;
  t += 'Assim que o pagamento for confirmado, o atendimento é liberado na hora.' + NL + NL;
} else {
  if (p.gratis_ate_definido === true && venc) t += 'Seu acesso está ativo' + (plano ? ' no plano *' + plano + '*' : '') + ', grátis até *' + venc + '*. Nada é cobrado agora: perto do fim do período grátis eu pergunto se quer continuar.' + NL + NL;
  else t += 'Seu acesso está ativo com *60 dias grátis*' + (venc ? ' (até ' + venc + ')' : '') + (plano ? ', no plano *' + plano + '*' : '') + '. Nada é cobrado agora: perto do fim do teste eu pergunto se quer continuar.' + NL + NL;
}
t += 'Somos dois no mesmo WhatsApp: o *Dyno* cuida do seu dinheiro e a *Dina* da sua agenda e rotina. Fale do seu jeito, por texto, áudio ou foto.' + NL + NL;
t += '*Para começar' + (p.sem_teste === true ? ' depois do pagamento' : ' agora') + ', experimente:*' + NL;
t += '💸 "gastei 30 no almoço"' + NL;
t += '📷 mande a foto de um cupom ou comprovante' + NL;
t += '⏰ "me lembra de pagar a luz dia 10"' + NL;
t += '📝 "cria uma lista de mercado: arroz, café, leite"' + NL;
t += '📅 "conectar agenda" para ligar o seu Google Agenda' + NL + NL;
t += '💻 *Sua área no site:* dynoapp.com.br/minhaconta, com painel, extrato, comprovantes, agenda e listas. Entra com um código que eu mando por aqui, sem senha.' + NL + NL;
t += '☀️ Todo dia às 7h30 chega o seu bom dia com o que vence e o que tem na agenda. Se preferir silêncio, é só dizer "pausar mensagens".' + NL + NL;
t += '📲 Siga o *@dynoapp.ia* no Instagram (instagram.com/dynoapp.ia) para ver dicas e novidades. Dúvidas e sugestões: é só responder aqui ou escrever para suporte@dynoapp.com.br.';
return [{ json: { falha: falha, motivo: 'cliente', usuario_id: p.usuario_id, corpo: { number: numero, text: ZW + t, delay: 800 } } }];

const ZW = String.fromCharCode(8203);
const numero = $('Normalizar mensagem').first().json.numero;
const r = $input.first().json || {};
// Se o RPC falhou (timeout, erro HTTP) não há 'acao': fica em silêncio, o cérebro já responde em paralelo.
if (!r.acao || r.acao === 'ignorar' || r.error) return [];
let texto = String(r.resposta || '');
if (!texto) return [];
const out = [{ json: { corpo: { number: numero, text: ZW + texto, delay: 800 } } }];
// Aviso para o Daniel (ex.: resposta de feedback de um piloto)
if (r.aviso_admin) out.push({ json: { corpo: { number: '5511930851325', text: ZW + String(r.aviso_admin), delay: 1500 } } });
return out;

const ZW = String.fromCharCode(8203);
const numero = $('Normalizar mensagem').first().json.numero;
const r = $('Supabase: comando admin').first().json || {};
if (r.acao === 'nao_admin') return [];
let texto = String(r.texto || '');
if (r.acao === 'asaas') {
  let a = {};
  const nome = r.metodo === 'PUT' ? 'Asaas: alterar assinatura (admin)' : 'Asaas: cancelar assinatura (admin)';
  try { a = $(nome).first().json || {}; } catch (e) { }
  const ok = a.deleted === true || (r.metodo === 'PUT' && !!a.id && !a.errors && !a.error);
  texto = ok ? String(r.texto_ok || '') : String(r.texto_falha || '');
}
if (!texto) texto = 'Não consegui executar o comando agora. Tente de novo em instantes.';
const out = [{ json: { corpo: { number: numero, text: ZW + texto, delay: 600 } } }];
// Mensagem extra (ex.: convite pronto para encaminhar) vai separada, para poder ser encaminhada inteira
if (r.extra) out.push({ json: { corpo: { number: numero, text: ZW + String(r.extra), delay: 1500 } } });
return out;

const ZW = String.fromCharCode(8203);
const NL = String.fromCharCode(10);
const ADMIN = '5511930851325';
const c = ($input.first().json || {}).corpo || {};
const t = String(c.text || '').split(ZW).join('');
const texto = String(c.number) === ADMIN
  ? '*Dyno (pelo seu número; o do Dyno está sem conexão):*' + NL + t
  : '⚠️ *Dyno sem conexão:* não consegui responder um cliente no cadastro. Reconecte a instância dyno na Evolution.';
return [{ json: { corpo: { number: ADMIN, text: ZW + texto, delay: 300 } } }];

const ZW = String.fromCharCode(8203);
const NL = String.fromCharCode(10);
const numero = $('Normalizar mensagem').first().json.numero;
const p = $('Supabase: passo do cadastro').first().json;
let sub = {}; let cob = {};
try { sub = $('Asaas: criar assinatura').first().json || {}; } catch (e) { }
try { cob = $('Asaas: cobrança da assinatura').first().json || {}; } catch (e) { }
const link = (cob.data && cob.data[0] && cob.data[0].invoiceUrl) || '';
const falha = !sub.id || !link;
const primeiro = String(p.nome || '').split(' ')[0];
const anual = p.ciclo === 'YEARLY';
const valor = 'R$ ' + Number(p.valor || (anual ? 199.9 : 19.9)).toFixed(2).replace('.', ',');
const forma = p.forma === 'CREDIT_CARD' ? 'cartão de crédito' : 'Pix';
const venc = String(p.vencimento || '').split('-').reverse().join('/');
let texto;
if (!falha) {
  texto = 'Combinado, ' + primeiro + '! Plano *' + (anual ? 'anual' : 'mensal') + '* (' + valor + (anual ? ' por ano' : ' por mês') + '), pagamento por *' + forma + '*.' + NL + NL +
    'Para ativar a assinatura, pague por este link' + (venc ? ' até ' + venc : '') + ':' + NL + link + NL + NL +
    'Ao finalizar o pagamento, você concorda com nossos Termos de Uso (dynoapp.com.br/termos) e confirma que leu nossa Política de Privacidade (dynoapp.com.br/privacidade). Você pode cancelar os pagamentos recorrentes a qualquer momento pela área do cliente (dynoapp.com.br/conta).';
} else {
  texto = 'Recebi sua escolha, ' + primeiro + '! Tive um problema para gerar o link de pagamento agora; já avisei a equipe e te mando o link em seguida. Nada foi cobrado.';
}
return [{ json: { falha: falha, motivo: 'assinatura', usuario_id: p.usuario_id, corpo: { number: numero, text: ZW + texto, delay: 800 } } }];
